// Vapi and Retell report a finished call in different shapes, and a plain
// POST in a third. All three are read here. The one field both platforms
// document the same way is the transcript, so nothing downstream depends on
// a vendor's own summary field.
const body = $json.body || $json || {};

let platform = 'unknown';
let callId = '';
let caller = '';
let transcript = '';
let endedReason = '';
let durationSeconds = 0;

// Vapi: the end of call report arrives nested under message.
const m = body.message;
if (m && String(m.type || '').toLowerCase().indexOf('end-of-call') !== -1) {
  platform = 'Vapi';
  endedReason = String(m.endedReason || '');
  transcript = String((m.artifact && m.artifact.transcript) || '');
  const call = m.call || {};
  callId = String(call.id || m.callId || '');
  caller = String(
    (call.customer && call.customer.number) ||
    (m.customer && m.customer.number) ||
    call.from || ''
  );
  if (call.startedAt && call.endedAt) {
    durationSeconds = Math.round((Date.parse(call.endedAt) - Date.parse(call.startedAt)) / 1000);
  }
}

// Retell: a flat event name with the call object beside it.
if (!platform || platform === 'unknown') {
  const ev = String(body.event || '').toLowerCase();
  if (ev === 'call_analyzed' || ev === 'call_ended') {
    platform = 'Retell';
    const call = body.call || {};
    callId = String(call.call_id || '');
    caller = String(call.from_number || '');
    transcript = String(call.transcript || '');
    endedReason = String(call.disconnection_reason || ev);
    if (call.start_timestamp && call.end_timestamp) {
      durationSeconds = Math.round((Number(call.end_timestamp) - Number(call.start_timestamp)) / 1000);
    }
  }
}

// Anything else, including a test POST.
if (!platform || platform === 'unknown') {
  platform = 'Direct';
  callId = String(body.callId || body.call_id || '');
  caller = String(body.caller || body.from || body.from_number || '');
  transcript = String(body.transcript || body.text || '');
  endedReason = String(body.endedReason || '');
  durationSeconds = Number(body.durationSeconds || 0) || 0;
}

if (!transcript.trim()) {
  throw new Error('No transcript on this call report. Check that the platform is sending the analyzed or end-of-call event, not the call-started event.');
}

// A caller who withholds their number still needs an identity for deduping,
// so fall back to the call id rather than grouping every anonymous caller
// into one incident.
const identity = caller.replace(/[^0-9+]/g, '') || ('call:' + callId);

return [{
  json: {
    platform: platform,
    callId: callId || ('gen-' + Date.now()),
    caller: caller || 'withheld',
    identity: identity,
    transcript: transcript.slice(0, 6000),
    endedReason: endedReason,
    durationSeconds: durationSeconds,
    receivedAt: new Date().toISOString(),
  },
}];

