// Put the triage together with what we already know about this caller. A
// worried person rings three times in five minutes; that is one incident, not
// three pages to the on-call engineer at two in the morning.
const call = $('Read The Call Report').first().json;
const settings = $('Load On Call Settings').first().json;
const prior = $('Recent Calls From This Caller').first().json || {};
const triage = $json.output || {};

const windowMinutes = Math.max(1, Number(settings['Repeat Caller Window Minutes'] || 20) || 20);
const escalateOn = String(settings['Escalate Severities'] || 'emergency,urgent')
  .split(',').map(function (s) { return s.trim().toLowerCase(); }).filter(Boolean);

const severity = String(triage.severity || 'routine').toLowerCase();
const now = Date.now();

const lastCallMs = Number(prior.lastCallMs || 0) || 0;
const withinWindow = lastCallMs > 0 && (now - lastCallMs) <= windowMinutes * 60000;
const alreadyHandled = String(prior.handled || 'no') === 'yes';
const alreadyEscalated = String(prior.escalated || 'no') === 'yes';

// Reuse the open incident when the same caller rings back inside the window
// and nobody has closed it yet.
const reuse = withinWindow && !alreadyHandled;
const incidentId = reuse && prior.incidentId
  ? String(prior.incidentId)
  : 'INC-' + new Date(now).toISOString().slice(0, 10).replace(/-/g, '') + '-' + String(now).slice(-5);

const callsInIncident = reuse ? (Number(prior.calls || 0) || 0) + 1 : 1;

// Escalate on severity, and also when someone calls back a third time about
// something we had filed as routine. Persistence is itself a signal.
const severityEscalates = escalateOn.indexOf(severity) !== -1;
const persistenceEscalates = callsInIncident >= 3;
const shouldEscalate = (severityEscalates || persistenceEscalates) && !alreadyEscalated && !alreadyHandled;

return [{
  json: {
    incidentId: incidentId,
    identity: call.identity,
    callId: call.callId,
    platform: call.platform,
    caller: call.caller,
    receivedAt: call.receivedAt,
    durationSeconds: call.durationSeconds,
    transcript: call.transcript,
    severity: severity,
    category: String(triage.category || 'other'),
    summary: String(triage.summary || '').slice(0, 500),
    callbackNeeded: !!triage.callbackNeeded,
    callerName: String(triage.callerName || ''),
    repeatCall: reuse,
    callsInIncident: callsInIncident,
    shouldEscalate: shouldEscalate,
    escalateReason: persistenceEscalates && !severityEscalates
      ? 'Third call from the same number inside the repeat window'
      : (severityEscalates ? 'Severity is ' + severity : ''),
    nowMs: now,
    businessName: String(settings['Business Name'] || 'the business'),
    onCallChannel: String(settings['On Call Slack Channel'] || '').trim(),
    backupChannel: String(settings['Backup Slack Channel'] || '').trim(),
    digestEmail: String(settings['Digest Email'] || '').trim(),
    alertText: '*After hours call, ' + severity + '*\n' +
      String(triage.summary || '').slice(0, 300) + '\n' +
      'Caller: ' + call.caller + (triage.callerName ? ' (' + triage.callerName + ')' : '') +
      '\nIncident: ' + incidentId + (callsInIncident > 1 ? ' (call ' + callsInIncident + ' from this number)' : '') +
      '\nCall back: ' + (triage.callbackNeeded ? 'yes' : 'not requested'),
  },
}];

// Everything that came in overnight, in the order a person should deal with
// it: what was escalated first, then what is still waiting on a call back,
// then the rest.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r['Call ID']; });

const since = Date.now() - 16 * 60 * 60 * 1000;
const overnight = rows.filter(function (r) {
  const t = Date.parse(r['Received At'] || '');
  return !isNaN(t) && t >= since;
});

if (!overnight.length) {
  return [{ json: { skip: true, subject: '', html: '' } }];
}

const rank = { emergency: 0, urgent: 1, routine: 2, spam: 3 };
const sorted = overnight.slice().sort(function (a, b) {
  const ra = rank[String(a['Severity'] || 'routine').toLowerCase()];
  const rb = rank[String(b['Severity'] || 'routine').toLowerCase()];
  if (ra !== rb) return ra - rb;
  return String(a['Received At']).localeCompare(String(b['Received At']));
});

const escalated = sorted.filter(function (r) { return String(r['Escalated'] || 'no') === 'yes'; });
const callbacks = sorted.filter(function (r) {
  return String(r['Callback Needed'] || 'no') === 'yes' && String(r['Escalated'] || 'no') !== 'yes';
});
const rest = sorted.filter(function (r) {
  return escalated.indexOf(r) === -1 && callbacks.indexOf(r) === -1;
});

function esc(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function block(title, list) {
  if (!list.length) return '';
  const items = list.map(function (r) {
    return '<li><b>' + esc(r['Severity']) + '</b> at ' + esc(String(r['Received At']).slice(11, 16)) +
      ' from ' + esc(r['Caller']) + ' - ' + esc(r['Summary']) +
      (String(r['Repeat Call'] || 'no') === 'yes' ? ' <i>(repeat caller)</i>' : '') + '</li>';
  }).join('');
  return '<h3>' + title + '</h3><ul>' + items + '</ul>';
}

const unique = {};
overnight.forEach(function (r) { unique[r['Incident ID']] = true; });

const html =
  '<h2>Overnight calls</h2>' +
  '<p>' + overnight.length + ' call' + (overnight.length > 1 ? 's' : '') + ' across ' +
  Object.keys(unique).length + ' incident' + (Object.keys(unique).length > 1 ? 's' : '') + '. ' +
  escalated.length + ' escalated during the night, ' + callbacks.length + ' waiting on a call back.</p>' +
  block('Escalated overnight', escalated) +
  block('Call these back this morning', callbacks) +
  block('Everything else', rest);

return [{
  json: {
    skip: false,
    calls: overnight.length,
    escalated: escalated.length,
    callbacks: callbacks.length,
    subject: 'Overnight calls: ' + overnight.length + ' total, ' + escalated.length + ' escalated, ' + callbacks.length + ' to call back',
    html: html,
  },
}];
